<body>
  <div class="protocol-container">
    <header>
      <h1>🎓 天海高等性斗学园商业街 🎓</h1>
      <div class="header-subtitle">Tianhai Academy Commercial Street - 学园商业街终端</div>
      <div class="currency-display">
        <div class="currency-item">
          <span class="currency-name">💰 学园金币:</span>
          <span class="currency-value academy-gold"
            id="academy-gold-display">{{get_message_variable::stat_data.基础档案.金钱}}</span>
        </div>
      </div>
    </header>

    <div class="category-bar" id="category-bar-container">
      <!-- Categories will be dynamically inserted here -->
    </div>

    <div class="main-content">
      <div class="item-list" id="item-list-container"></div>
      <div class="item-detail-wrapper" id="item-detail-wrapper">
        <div class="detail-placeholder" id="detail-placeholder">
          <p>正在初始化学园商店...</p>
        </div>
        <div class="detail-error" id="detail-error" style="display: none;">
          <p>数据流中断或解析失败。<br>请检查输入源是否符合商店格式。</p>
        </div>
        <div class="detail-content" id="detail-content-area"></div>
      </div>
    </div>

    <div class="cart-container">
      <h2 class="cart-title">🛒 已选择商品</h2>
      <div class="cart-items" id="cart-items-container">
        <!-- Cart items will be dynamically inserted here -->
      </div>
      <div class="cart-footer">
        <div class="cart-total">
          <span class="cart-total-label">合计:</span>
          <span class="cart-total-price" id="cart-total-price">0</span>
        </div>
        <button class="checkout-btn" id="checkout-btn">🛍️ 确认购买</button>
      </div>
    </div>
  </div>

  <div class="hidden-input-area">
    <textarea id="data-input">$1</textarea>
  </div>

  <script>
    // 使用jQuery确保在酒馆环境中正确加载
    $(() => {
      const dataInput = document.getElementById('data-input');
      const itemListContainer = document.getElementById('item-list-container');
      const detailWrapper = document.getElementById('item-detail-wrapper');
      const detailPlaceholder = document.getElementById('detail-placeholder');
      const detailError = document.getElementById('detail-error');
      const detailContentArea = document.getElementById('detail-content-area');
      const categoryBarContainer = document.getElementById('category-bar-container');
      const cartItemsContainer = document.getElementById('cart-items-container');
      const cartTotalPrice = document.getElementById('cart-total-price');
      const checkoutBtn = document.getElementById('checkout-btn');
      const academyGoldDisplay = document.getElementById('academy-gold-display');

      let cart = [];
      let allItems = [];
      let currentTotalCost = 0;

      function mapSortToCategoryKey(sortString) {
        const mapping = {
          '装备类商品': 'equipment',
          '好感度商品': 'gifts',
          '特殊商品': 'special',
          '生活用品': 'daily'
        };
        for (const key in mapping) {
          if (sortString.includes(key)) return mapping[key];
        }
        return 'other';
      }

      function initializeProtocol(rawData) {
        allItems = parseSupplyItems(rawData);
        if (allItems.length > 0) {
          displayCategoryButtons(allItems);
          displayItemsList(allItems);
          setupCategoryFilters();
          clearDetailView();
          renderCart();
        } else {
          showError();
        }
      }

      function parseSupplyItems(data) {
        let contentToParse = data;
        const protocolContentMatch = data.match(/<学园商业街供应协议>([\s\S]+?)<\/学园商业街供应协议>/);

        if (protocolContentMatch) {
          contentToParse = protocolContentMatch[1];
        }

        const parsedItems = [];
        const itemRegex = /<item>\s*<supply>([\s\S]*?)<\/supply>\s*<sort>([\s\S]*?)<\/sort>\s*<price>([\s\S]*?)<\/price>(?:\s*<unit>([\s\S]*?)<\/unit>)?\s*<info>([\s\S]*?)<\/info>\s*<\/item>/g;
        let match;

        while ((match = itemRegex.exec(contentToParse)) !== null) {
          const [, supply, sort, price, unit, info] = match.map(s => s ? s.trim() : s);

          const originalSort = sort || '其他';
          const categoryKey = mapSortToCategoryKey(originalSort);
          const priceValue = parseFloat(price.replace(/[^0-9.-]+/g, "")) || 0;

          parsedItems.push({
            id: `item-${parsedItems.length}`,
            supply: supply,
            sort: categoryKey,
            originalSort: originalSort,
            price: price,
            priceValue: priceValue,
            unit: unit || null,
            info: info || '无详细信息。'
          });
        }
        return parsedItems;
      }

      function displayCategoryButtons(items) {
        const categories = new Map();
        categories.set('all', '全部');

        items.forEach(item => {
          if (!Array.from(categories.keys()).includes(item.sort)) {
            categories.set(item.sort, item.originalSort);
          }
        });

        categoryBarContainer.innerHTML = '';
        categories.forEach((value, key) => {
          const button = document.createElement('button');
          button.className = 'category-btn';
          button.dataset.category = key;
          button.textContent = value;
          if (key === 'all') {
            button.classList.add('active');
          }
          categoryBarContainer.appendChild(button);
        });
      }

      function displayItemsList(items) {
        itemListContainer.innerHTML = '';
        items.forEach(item => {
          const card = document.createElement('div');
          card.className = 'item-card';
          card.id = item.id;
          card.dataset.sort = item.sort;
          card.innerHTML = `<div class="item-name">${item.supply}</div><div class="item-price">${item.price}</div>`;
          card.addEventListener('click', () => {
            displayItemDetail(item);
            document.querySelectorAll('.item-card').forEach(c => c.classList.remove('active'));
            card.classList.add('active');
          });
          itemListContainer.appendChild(card);
        });
      }

      function displayItemDetail(item) {
        detailPlaceholder.style.display = 'none';
        detailError.style.display = 'none';
        detailContentArea.style.display = 'flex';

        let unitHtml = '';
        if (item.unit) {
          unitHtml = `
                    <div class="detail-section">
                        <div class="detail-label">单位</div>
                        <div class="detail-value">${item.unit}</div>
                    </div>`;
        }

        detailContentArea.innerHTML = `
                    <div class="detail-header">
                        <div class="detail-name">${item.supply}</div>
                        <div class="detail-price">${item.price}</div>
                    </div>
                    <div class="detail-section">
                        <div class="detail-label">分类</div>
                        <div class="detail-value">${item.originalSort}</div>
                    </div>
                    ${unitHtml}
                    <div class="detail-section">
                        <div class="detail-label">信息</div>
                        <div class="detail-value">${item.info}</div>
                    </div>
                    <div class="detail-section">
                        <div class="detail-label">数量</div>
                        <div class="quantity-selector">
                            <button class="quantity-btn" id="decrease-quantity">-</button>
                            <input type="number" class="quantity-input" id="quantity-input" value="1" min="1">
                            <button class="quantity-btn" id="increase-quantity">+</button>
                        </div>
                    </div>
                    <button class="add-to-cart-btn" id="add-to-cart">🛍️ 加入购物车</button>`;

        document.getElementById('decrease-quantity').addEventListener('click', () => {
          const input = document.getElementById('quantity-input');
          let value = parseInt(input.value);
          if (value > 1) input.value = value - 1;
        });

        document.getElementById('increase-quantity').addEventListener('click', () => {
          const input = document.getElementById('quantity-input');
          input.value = parseInt(input.value) + 1;
        });

        document.getElementById('add-to-cart').addEventListener('click', () => {
          const quantity = parseInt(document.getElementById('quantity-input').value);
          addToCart(item, quantity);
        });
      }

      function addToCart(item, quantity) {
        const existingItem = cart.find(cartItem => cartItem.id === item.id);
        if (existingItem) {
          existingItem.quantity += quantity;
        } else {
          cart.push({ ...item, quantity: quantity });
        }
        renderCart();
      }

      function renderCart() {
        cartItemsContainer.innerHTML = '';
        let totalGold = 0;

        cart.forEach(item => {
          const cartItemElement = document.createElement('div');
          cartItemElement.className = 'cart-item';
          cartItemElement.innerHTML = `
                        <span class="cart-item-name">${item.supply}</span>
                        <div class="cart-item-quantity">
                            <button class="quantity-btn cart-quantity-btn" data-id="${item.id}" data-change="-1">-</button>
                            <span>${item.quantity}</span>
                            <button class="quantity-btn cart-quantity-btn" data-id="${item.id}" data-change="1">+</button>
                        </div>
                        <span class="cart-item-price">${(item.priceValue * item.quantity).toFixed(0)}学园金币</span>
                    `;
          cartItemsContainer.appendChild(cartItemElement);

          totalGold += item.priceValue * item.quantity;
        });

        currentTotalCost = totalGold;
        cartTotalPrice.textContent = `${totalGold.toFixed(0)}学园金币`;

        document.querySelectorAll('.cart-quantity-btn').forEach(button => {
          button.addEventListener('click', (e) => {
            const itemId = e.target.dataset.id;
            const change = parseInt(e.target.dataset.change);
            updateCartQuantity(itemId, change);
          });
        });
      }

      function updateCartQuantity(itemId, change) {
        const itemIndex = cart.findIndex(item => item.id === itemId);
        if (itemIndex > -1) {
          cart[itemIndex].quantity += change;
          if (cart[itemIndex].quantity <= 0) {
            cart.splice(itemIndex, 1);
          }
        }
        renderCart();
      }

      function setupCategoryFilters() {
        const categoryButtons = document.querySelectorAll('.category-btn');
        categoryButtons.forEach(button => {
          button.addEventListener('click', () => {
            const category = button.dataset.category;
            categoryButtons.forEach(btn => btn.classList.remove('active'));
            button.classList.add('active');
            const allItemCards = document.querySelectorAll('.item-card');
            allItemCards.forEach(card => {
              if (category === 'all' || card.dataset.sort === category) {
                card.classList.remove('hidden');
              } else {
                card.classList.add('hidden');
              }
            });
            clearDetailView();
          });
        });
      }

      function clearDetailView() {
        detailContentArea.style.display = 'none';
        detailError.style.display = 'none';
        detailPlaceholder.style.display = 'block';
        detailPlaceholder.innerHTML = '<p>🛍️ 从列表中选择商品查看详情</p>';
        document.querySelectorAll('.item-card').forEach(c => c.classList.remove('active'));
      }

      function showError() {
        detailContentArea.style.display = 'none';
        detailPlaceholder.style.display = 'none';
        detailError.style.display = 'block';
      }

      function decodeHtml(html) {
        var txt = document.createElement("textarea");
        txt.innerHTML = html;
        return txt.value;
      }

      checkoutBtn.addEventListener('click', () => {
        if (cart.length === 0) {
          alert('🛍️ 购物车为空！请先选择商品。');
          return;
        }

        // 直接从显示元素获取当前金币（因为显示是通过MVU模板更新的）
        let currentGold = 0;
        const displayText = academyGoldDisplay.textContent;

        // 如果显示的是数组格式 [1500,"描述"]，提取第一个数字
        if (displayText.includes('[') && displayText.includes(']')) {
          const match = displayText.match(/\[(\d+(?:\.\d+)?),/);
          if (match) {
            currentGold = parseFloat(match[1]) || 0;
          }
        } else {
          // 如果显示的是纯数字，直接解析
          const cleanText = displayText.replace(/[^\d.-]/g, '');
          currentGold = parseFloat(cleanText) || 0;
        }

        // 如果还是0，尝试从酒馆变量获取
        if (currentGold === 0) {
          try {
            if (typeof getVariables !== 'undefined') {
              const variables = getVariables({ type: 'global' });
              if (variables && variables.stat_data && variables.stat_data.基础档案 && variables.stat_data.基础档案.金钱) {
                currentGold = parseFloat(variables.stat_data.基础档案.金钱[0]) || 0;
              }
            }
          } catch (e) {
            console.log('无法从酒馆变量获取金币:', e);
          }
        }

        // 调试信息
        console.log('当前金币:', currentGold, '总花费:', currentTotalCost);

        if (currentGold < currentTotalCost) {
          alert(`💰 学园金币不足！\n当前金币: ${currentGold}\n需要金币: ${currentTotalCost}`);
          return;
        }

        const itemsParts = cart.map(item => {
          let unitString = item.unit;
          if (!unitString) {
            const priceParts = item.price.split('/');
            unitString = priceParts.length > 1 ? priceParts[1] : '份';
          }

          const unitMatch = unitString.match(/^(\d*\.?\d+)(.*)$/);
          if (unitMatch) {
            const unitValue = parseFloat(unitMatch[1]);
            const unitName = unitMatch[2] || '';
            const totalAmount = item.quantity * unitValue;
            return `${item.supply}，${totalAmount}${unitName}`;
          } else {
            return `${item.supply}，${item.quantity}${unitString}`;
          }
        });

        const checkoutMessage = `花费${currentTotalCost.toFixed(0)}学园金币，购买清单：${itemsParts.join('；')}。`;

        // 复制到剪贴板
        try {
          if (navigator.clipboard && window.isSecureContext) {
            // 使用现代剪贴板API
            navigator.clipboard.writeText(checkoutMessage).then(() => {
              alert('🛍️ 购买信息已复制到剪贴板！\n\n请手动发送消息。');
              cart = [];
              renderCart();
            }).catch(() => {
              // 如果现代API失败，使用传统方法
              fallbackCopyToClipboard(checkoutMessage);
            });
          } else {
            // 使用传统方法
            fallbackCopyToClipboard(checkoutMessage);
          }
        } catch (err) {
          console.error('复制失败:', err);
          alert('🛍️ 购买成功！\n\n购买信息：' + checkoutMessage);
          cart = [];
          renderCart();
        }

        function fallbackCopyToClipboard(text) {
          const textArea = document.createElement('textarea');
          textArea.value = text;
          textArea.style.position = 'fixed';
          textArea.style.left = '-999999px';
          textArea.style.top = '-999999px';
          document.body.appendChild(textArea);
          textArea.focus();
          textArea.select();

          try {
            const successful = document.execCommand('copy');
            if (successful) {
              alert('🛍️ 购买信息已复制到剪贴板！\n\n请手动发送消息。');
            } else {
              alert('🛍️ 购买成功！\n\n购买信息：' + text);
            }
          } catch (err) {
            console.error('复制失败:', err);
            alert('🛍️ 购买成功！\n\n购买信息：' + text);
          }

          document.body.removeChild(textArea);
          cart = [];
          renderCart();
        }
      });

      // 尝试从酒馆变量获取数据
      function tryLoadFromTavernVariables() {
        try {
          // 尝试使用酒馆助手接口获取数据
          if (typeof getVariables !== 'undefined') {
            const variables = getVariables({ type: 'global' });
            if (variables && variables.学园商业街供应协议) {
              initializeProtocol(variables.学园商业街供应协议);
              return true;
            }
          }
        } catch (e) {
          console.log('无法从酒馆变量获取数据:', e);
        }
        return false;
      }

      // 尝试从输入框获取数据
      function tryLoadFromInput() {
        const interval = 50, timeout = 2000; let elapsedTime = 0;
        const dataObserver = setInterval(() => {
          const rawData = dataInput.value;
          elapsedTime += interval;
          if (rawData && rawData.trim() !== '$' + '1') {
            clearInterval(dataObserver);
            const decodedData = decodeHtml(rawData);
            initializeProtocol(decodedData);
          } else if (elapsedTime >= timeout) {
            clearInterval(dataObserver);
            showError();
          }
        }, interval);
      }

      // 优先尝试从酒馆变量加载，失败则从输入框加载
      if (!tryLoadFromTavernVariables()) {
        tryLoadFromInput();
      }

      // 添加示例数据作为备用
      setTimeout(() => {
        if (allItems.length === 0) {
          const sampleData = `<学园商业街供应协议>
