        <!-- 计算公式说明 -->
        <div class="section">
          <div class="section-header clickable" onclick="toggleSection(this)">计算公式说明</div>
          <div class="section-content">
            <div style="color: var(--text-secondary); font-size: 0.9em; line-height: 1.6;">
              <div style="margin-bottom: 15px;">
                <strong style="color: var(--accent-highlight);">性斗力计算公式：</strong><br>
                性斗力 = (等级 × 潜力) + 装备加成 + 基础值7
              </div>
              <div style="margin-bottom: 15px;">
                <strong style="color: var(--accent-highlight);">忍耐力计算公式：</strong><br>
                忍耐力 = (等级 × 潜力 × 0.8) + 装备加成 + 基础值50
              </div>
              <div style="margin-bottom: 15px;">
                <strong style="color: var(--accent-highlight);">最大快感值计算公式：</strong><br>
                最大快感值 = (等级 × 潜力 × 2) + 忍耐力 + 基础值100
              </div>
              <div style="margin-bottom: 15px;">
                <strong style="color: var(--accent-highlight);">经验值升级：</strong><br>
                每级需要100点经验值，升级后各项属性按公式重新计算
              </div>
