  <script>
    // 数据读取函数
    function GetRawValue(obj, path, defaultValue = null) {
      const keys = Array.isArray(path) ? path : path.split('.');
      let current = obj;
      for (let i = 0; i < keys.length; i++) {
        const key = keys[i];
        if (current === undefined || current === null || typeof current !== 'object' || !current.hasOwnProperty(key)) {
          return defaultValue;
        }
        current = current[key];
      }
      return current === undefined || current === null ? defaultValue : current;
    }

    function SafeGetValue(obj, path, defaultValue = 'N/A') {
      const keys = Array.isArray(path) ? path : path.split('.');
      let current = obj;
      for (let i = 0; i < keys.length; i++) {
        const key = keys[i];
        if (current === undefined || current === null || typeof current !== 'object' || !current.hasOwnProperty(key)) {
          return defaultValue;
        }
        current = current[key];
      }

      if (current === undefined || current === null) {
        return defaultValue;
      }

      if (Array.isArray(current) && current.length > 0) {
        const actualValue = current[0];
        return typeof actualValue === 'boolean' ? actualValue : String(actualValue);
      }

      return typeof current === 'boolean' ? current : String(current);
    }

    // 进度条更新函数
    function updateProgressBar(barId, valueMainId, valueDescId, rawValue, min, max, stageMapping) {
      const progressBar = document.getElementById(barId);
      const valueMainDisplay = document.getElementById(valueMainId);
      const valueDescDisplay = document.getElementById(valueDescId);

      if (!valueMainDisplay) return;

      const numericValue = parseFloat(rawValue) || min;
      valueMainDisplay.innerText = String(rawValue);

      if (valueDescDisplay && stageMapping) {
        const stage = stageMapping.find(s => numericValue >= s.min && numericValue <= s.max);
        valueDescDisplay.innerText = stage ? stage.name : '';
      }

      if (progressBar) {
        const clampedValue = Math.max(min, Math.min(max, numericValue));
        const range = max - min;
        const percentage = range === 0 ? (clampedValue >= max ? 100 : 0) : ((clampedValue - min) / range) * 100;
        progressBar.style.width = `${percentage}%`;

        if (stageMapping) {
          const stage = stageMapping.find(s => clampedValue >= s.min && clampedValue <= s.max);
          if (stage && stage.color) {
            progressBar.style.background = `linear-gradient(90deg, ${stage.color}, var(--accent-bond))`;
          }
        }
      }
    }

    let statDataCache = null;

    // 页面切换函数
    function switchPage(pageId) {
      document.querySelectorAll('.pagination-content').forEach(page => {
        page.classList.remove('active');
      });

      document.querySelectorAll('.pagination-tab').forEach(tab => {
        tab.classList.remove('active');
      });

      document.getElementById(pageId + '-page').classList.add('active');
      event.target.classList.add('active');
    }

    // 章节切换函数
    function toggleSection(headerElement) {
      const content = headerElement.nextElementSibling;
      if (content) {
        const isVisible = content.classList.contains('active');
        content.classList.toggle('active');
        headerElement.classList.toggle('expanded');
      }
    }

    // 渲染派系关系
    function renderFactionRelationships() {
      const factionContainer = document.getElementById('faction-relationships');
      const factionOverview = document.getElementById('faction-overview');

      if (!statDataCache) return;

      const factions = GetRawValue(statDataCache, '学园信息.派系关系', {});

      let factionHTML = '';
      let overviewHTML = '';

      for (const factionName in factions) {
        if (factionName === '$meta') continue;

        const faction = factions[factionName];
        const relationValue = SafeGetValue(faction, '关系值', '0');
        const description = SafeGetValue(faction, '描述', '');
        const leader = SafeGetValue(faction, '领导', '');
        const features = GetRawValue(faction, '特点', []);
        const highRewards = GetRawValue(faction, '高关系奖励', {});

        const relationColor = relationValue > 0 ? 'var(--accent-bond)' :
          relationValue < 0 ? 'var(--accent-danger)' : 'var(--text-secondary)';

        // 处理特点数组
        let featuresText = '';
        if (Array.isArray(features)) {
          featuresText = features.map(feature => {
            if (Array.isArray(feature)) {
              return feature[0]; // 取数组的第一个值
            }
            return feature;
          }).join('、');
        } else if (typeof features === 'object' && features !== null) {
          featuresText = Object.values(features).map(feature => {
            if (Array.isArray(feature)) {
              return feature[0];
            }
            return feature;
          }).join('、');
        }

        // 处理高关系奖励
        let rewardsText = '';
        if (highRewards && Object.keys(highRewards).length > 0) {
          const rewards = Object.entries(highRewards).map(([key, value]) => {
            return `${key}: ${value}`;
          }).join('; ');
          rewardsText = rewards;
        }

        const factionHTML_item = `
            <div class="faction-relation" style="flex-direction: column; align-items: flex-start; padding: 15px;">
              <div style="display: flex; justify-content: space-between; width: 100%; margin-bottom: 8px;">
                <div class="faction-name" style="font-size: 1.1em; font-weight: 700;">${factionName}</div>
                <div class="faction-value" style="color: ${relationColor}; font-size: 1.1em;">${relationValue}</div>
              </div>
              ${leader && leader !== 'N/A' ? `<div style="color: var(--accent-highlight); font-size: 0.9em; margin-bottom: 5px;">领导: ${leader}</div>` : ''}
              ${description && description !== 'N/A' ? `<div style="color: var(--text-secondary); font-size: 0.85em; line-height: 1.4; margin-bottom: 5px;">${description}</div>` : ''}
              ${featuresText ? `<div style="color: var(--accent-warning); font-size: 0.8em; margin-bottom: 5px;">特点: ${featuresText}</div>` : ''}
              ${rewardsText ? `<div style="color: var(--accent-bond); font-size: 0.8em; line-height: 1.3;">高关系奖励: ${rewardsText}</div>` : ''}
            </div>
          `;

        factionHTML += factionHTML_item;
        overviewHTML += factionHTML_item;
      }

      if (factionContainer) factionContainer.innerHTML = factionHTML;
      if (factionOverview) factionOverview.innerHTML = overviewHTML;
    }

    // 渲染NPC关系
    function renderNPCRelationships() {
      const npcContainer = document.getElementById('npc-relationships');
      if (!statDataCache || !npcContainer) return;

      const npcs = GetRawValue(statDataCache, 'NPC角色', {});
      let npcHTML = '';

      for (const npcKey in npcs) {
        if (npcKey === '$meta') continue;

        const npc = npcs[npcKey];
        const npcName = SafeGetValue(npc, '基础档案.姓名', '');
        const npcIdentity = SafeGetValue(npc, '基础档案.身份', '');
        const npcGender = SafeGetValue(npc, '基础档案.性别', '');
        const npcAppearanceRaw = SafeGetValue(npc, '基础档案.外貌描述', '');
        const npcAppearance = Array.isArray(npcAppearanceRaw) ? npcAppearanceRaw[0] : npcAppearanceRaw;
        const npcLevel = SafeGetValue(npc, '基础档案.等级', '');
        const npcRank = SafeGetValue(npc, '基础档案.段位', '');
        const npcCombatPower = SafeGetValue(npc, '核心状态.性斗力', '');
        const npcEndurance = SafeGetValue(npc, '核心状态.忍耐力', '');
        const npcMaxPleasure = SafeGetValue(npc, '核心状态.最大快感值', '');
        const npcCharm = SafeGetValue(npc, '核心状态.魅力', '');
        const npcLuck = SafeGetValue(npc, '核心状态.幸运值', '');
        const npcAffinity = SafeGetValue(npc, '关系状态.好感度', '0');
        const npcRelationType = SafeGetValue(npc, '关系状态.关系类型', '');
        const npcRelationStatus = SafeGetValue(npc, '关系状态.关系状态', '');
        const npcFaction = SafeGetValue(npc, '关系状态.派系归属', '');
        const npcPersonality = SafeGetValue(npc, '性格特征.基础性格', '');
        const npcBehavior = SafeGetValue(npc, '性格特征.行为模式', '');

        if (npcName && npcName !== 'N/A') {
          const affinityColor = npcAffinity > 0 ? 'var(--accent-bond)' :
            npcAffinity < 0 ? 'var(--accent-danger)' : 'var(--text-secondary)';

          npcHTML += `
            <div class="expandable-item" onclick="toggleItemDetails(this)">
              <div class="item-header">
                <span class="equipment-name">${npcName}</span>
                <span class="equipment-level" style="color: ${affinityColor};">好感度: ${npcAffinity}</span>
                <span class="expand-icon">▼</span>
              </div>
              <div class="item-details" style="display: none;">
                <div class="detail-row">
                  <span class="detail-label">身份:</span>
                  <span class="detail-value">${npcIdentity}</span>
                </div>
                <div class="detail-row">
                  <span class="detail-label">性别:</span>
                  <span class="detail-value">${npcGender}</span>
                </div>
                ${npcAppearance && npcAppearance !== 'N/A' ? `<div class="detail-row">
                  <span class="detail-label">外貌描述:</span>
                  <span class="detail-value">${npcAppearance}</span>
                </div>` : ''}
                <div class="detail-row">
                  <span class="detail-label">等级:</span>
                  <span class="detail-value">${npcLevel}</span>
                </div>
                <div class="detail-row">
                  <span class="detail-label">段位:</span>
                  <span class="detail-value">${npcRank}</span>
                </div>
                <div class="detail-row">
                  <span class="detail-label">性斗力:</span>
                  <span class="detail-value">${npcCombatPower}</span>
                </div>
                <div class="detail-row">
                  <span class="detail-label">忍耐力:</span>
                  <span class="detail-value">${npcEndurance}</span>
                </div>
                ${npcMaxPleasure && npcMaxPleasure !== 'N/A' ? `<div class="detail-row">
                  <span class="detail-label">最大快感值:</span>
                  <span class="detail-value">${npcMaxPleasure}</span>
                </div>` : ''}
                <div class="detail-row">
                  <span class="detail-label">魅力:</span>
                  <span class="detail-value">${npcCharm}</span>
                </div>
                <div class="detail-row">
                  <span class="detail-label">幸运值:</span>
                  <span class="detail-value">${npcLuck}</span>
                </div>
                <div class="detail-row">
                  <span class="detail-label">关系类型:</span>
                  <span class="detail-value">${npcRelationType}</span>
                </div>
                <div class="detail-row">
                  <span class="detail-label">关系状态:</span>
                  <span class="detail-value">${npcRelationStatus}</span>
                </div>
                ${npcFaction && npcFaction !== 'N/A' ? `<div class="detail-row">
                  <span class="detail-label">派系归属:</span>
                  <span class="detail-value">${npcFaction}</span>
                </div>` : ''}
                <div class="detail-row">
                  <span class="detail-label">性格:</span>
                  <span class="detail-value">${npcPersonality}</span>
                </div>
                <div class="detail-row">
                  <span class="detail-label">行为模式:</span>
                  <span class="detail-value">${npcBehavior}</span>
                </div>
              </div>
            </div>
          `;
        }
      }

      npcContainer.innerHTML = npcHTML || '<div class="equipment-item"><span class="equipment-name">暂无NPC</span></div>';
    }

    // 渲染物品列表
    function renderInventory() {
      const inventoryContainer = document.getElementById('inventory-list');
      if (!statDataCache || !inventoryContainer) return;

      const inventory = GetRawValue(statDataCache, '装备与物品.持有物品', {});
      let inventoryHTML = '';

      for (const itemKey in inventory) {
        if (itemKey === '$meta') continue;

        const item = inventory[itemKey];
