      window.addEventListener('click', (event) => {
        if (event.target == document.getElementById('npc-interaction-modal')) {
          closeNPCInteractionModal();
        }
      });
    });

    // 显示NPC详情
    function showNPCDetails(npcName) {
      if (!statDataCache) return;

      const npcListData = GetRawValue(statDataCache, 'NPC角色', {});
      const npcData = Object.values(npcListData).find(item =>
        item && typeof item === 'object' &&
        SafeGetValue(item, '基础档案.姓名', '') === npcName
      );

      if (!npcData) return;

      const gender = SafeGetValue(npcData, '基础档案.性别', '男性');
      const identity = SafeGetValue(npcData, '基础档案.身份', 'N/A');
      const appearanceRaw = SafeGetValue(npcData, '基础档案.外貌描述', 'N/A');
      const appearance = Array.isArray(appearanceRaw) ? appearanceRaw[0] : appearanceRaw;
      const level = SafeGetValue(npcData, '基础档案.等级', 'N/A');
      const rank = SafeGetValue(npcData, '基础档案.段位', 'N/A');
      const combatPower = SafeGetValue(npcData, '核心状态.性斗力', 'N/A');
      const endurance = SafeGetValue(npcData, '核心状态.忍耐力', 'N/A');
      const maxPleasure = SafeGetValue(npcData, '核心状态.最大快感值', 'N/A');
      const charm = SafeGetValue(npcData, '核心状态.魅力', 'N/A');
      const luck = SafeGetValue(npcData, '核心状态.幸运值', 'N/A');

      let bodyPartsInfo = '';
      const bodyParts = GetRawValue(npcData, '身体部位', {});

      // 根据性别显示不同的身体部位
      const bodyPartKeys = ['胸部', '菊穴', '脚部'];
      if (gender === '女性') {
        bodyPartKeys.splice(1, 0, '小穴');
      } else if (gender === '男性') {
        bodyPartKeys.splice(1, 0, '肉棒');
      } else if (gender === '扶他') {
        bodyPartKeys.splice(1, 0, '肉棒', '小穴');
      }

      for (const partKey of bodyPartKeys) {
        const partData = bodyParts[partKey];
        if (!partData) continue;

        let partInfo = '';
        if (partKey === '胸部') {
          const size = SafeGetValue(partData, '大小', 'N/A');
          const sensitivity = SafeGetValue(partData, '敏感度', 'N/A');
          partInfo = `${size} | 敏感度:${sensitivity}`;
        } else if (partKey === '肉棒') {
          const length = SafeGetValue(partData, '长度', 'N/A');
          const thickness = SafeGetValue(partData, '粗细', 'N/A');
          const sensitivity = SafeGetValue(partData, '敏感度', 'N/A');
          partInfo = `${length} | ${thickness} | 敏感度:${sensitivity}`;
        } else if (partKey === '小穴') {
          const tightness = SafeGetValue(partData, '紧致度', 'N/A');
          const wetness = SafeGetValue(partData, '湿润度', 'N/A');
          const sensitivity = SafeGetValue(partData, '敏感度', 'N/A');
          partInfo = `${tightness} | 湿润度:${wetness} | 敏感度:${sensitivity}`;
        } else if (partKey === '菊穴') {
          const tightness = SafeGetValue(partData, '紧致度', 'N/A');
          const sensitivity = SafeGetValue(partData, '敏感度', 'N/A');
          partInfo = `${tightness} | 敏感度:${sensitivity}`;
        } else if (partKey === '脚部') {
          const size = SafeGetValue(partData, '大小', 'N/A');
          const sensitivity = SafeGetValue(partData, '敏感度', 'N/A');
          partInfo = `${size} | 敏感度:${sensitivity}`;
        }

        bodyPartsInfo += `${partKey}: ${partInfo}\n`;
      }

      const details = `NPC详情信息：

姓名: ${npcName}
性别: ${gender}
身份: ${identity}
${appearance && appearance !== 'N/A' ? `外貌描述: ${appearance}` : ''}
等级: ${level}
段位: ${rank}

核心状态:
性斗力: ${combatPower}
忍耐力: ${endurance}
${maxPleasure && maxPleasure !== 'N/A' ? `最大快感值: ${maxPleasure}` : ''}
魅力: ${charm}
幸运值: ${luck}

身体部位:
${bodyPartsInfo}`;

      alert(details);
    }

