      const orgasmBar = document.getElementById('opponent-orgasm-bar');
      const orgasmText = document.getElementById('opponent-orgasm-text');
      orgasmBar.style.width = `${(opponentOrgasm / 3) * 100}%`;
      orgasmText.textContent = `${opponentOrgasm}/3`;

      // 更新忍耐力条
      const enduranceBar = document.getElementById('opponent-endurance-bar');
      const enduranceText = document.getElementById('opponent-endurance-text');
      const opponentMaxEndurance = SafeGetValue(statData, '性斗系统.对手信息.最大忍耐力', opponentEndurance);
      const endurancePercentage = (opponentEndurance / opponentMaxEndurance) * 100;
      enduranceBar.style.width = `${Math.min(endurancePercentage, 100)}%`;
      enduranceText.textContent = `${opponentEndurance}/${opponentMaxEndurance}`;

      // 更新性斗力条（以100为基准显示）
      const combatBar = document.getElementById('opponent-combat-bar');
      const combatText = document.getElementById('opponent-combat-text');
      combatBar.style.width = `${Math.min(opponentCombatPower * 5, 100)}%`; // 性斗力*5作为百分比
      combatText.textContent = `${opponentCombatPower}`;
    }

    // 更新技能列表
    function updateCombatSkills(statData) {
      const playerSkillsGrid = document.getElementById('player-skills-grid');
      const playerSkills = GetRawValue(statData, '技能系统.主动技能', {});

      // 更新玩家技能
      let playerSkillsHTML = '';
      for (const skillKey in playerSkills) {
        if (skillKey === '$meta') continue;

        const skill = playerSkills[skillKey];
        const skillName = SafeGetValue(skill, '名称', '');
        const skillCost = SafeGetValue(skill, '消耗', '');
        const skillCooldown = SafeGetValue(skill, '冷却时间', '');
        const skillDescription = SafeGetValue(skill, '描述', '');
        const skillEffect = SafeGetValue(skill, '效果', '');

        if (skillName && skillName !== 'N/A') {
          playerSkillsHTML += `
            <div class="skill-item" data-skill="${skillName}" onclick="toggleSkillDetails(this)">
              <div class="skill-header">
                <div class="skill-name">${skillName}</div>
                <div class="skill-cost">消耗: ${skillCost}</div>
                <div class="skill-cooldown">冷却: ${skillCooldown}回合</div>
                <div class="expand-icon">▼</div>
              </div>
              <div class="skill-details" style="display: none;">
                <div class="skill-description">
                  <strong>技能描述：</strong>${skillDescription || '暂无描述'}
                </div>
                <div class="skill-effect">
                  <strong>技能效果：</strong>${skillEffect || '暂无效果说明'}
                </div>
                <button class="use-skill-button" onclick="useSkill('${skillName}')">发动技能</button>
              </div>
            </div>
          `;
        }
      }
      playerSkillsGrid.innerHTML = playerSkillsHTML || '<div style="text-align: center; color: #666;">暂无可用技能</div>';
    }

    // 更新被动技能列表
    function updatePassiveSkills(statData) {
      const passiveSkillsGrid = document.getElementById('passive-skills-grid');
      if (!passiveSkillsGrid) return;

      const passiveSkills = GetRawValue(statData, '技能系统.被动技能', {});

      let passiveSkillsHTML = '';
      let skillCount = 0;

      for (const skillKey in passiveSkills) {
        if (skillKey === '$meta') continue;

        const skill = passiveSkills[skillKey];
        const skillName = SafeGetValue(skill, '名称', '');
        const skillLevel = SafeGetValue(skill, '等级', '');
        const skillEffect = SafeGetValue(skill, '效果', '');
        const skillDescription = SafeGetValue(skill, '描述', '');

        if (skillName && skillName !== 'N/A') {
          skillCount++;
          passiveSkillsHTML += `
            <div class="skill-item" data-skill="${skillName}" onclick="toggleSkillDetails(this)">
              <div class="skill-header">
                <div class="skill-name">${skillName} (Lv.${skillLevel})</div>
                <div class="expand-icon">▼</div>
              </div>
              <div class="skill-details" style="display: none;">
                <div class="skill-description">
                  <strong>技能描述：</strong>${skillDescription || '暂无描述'}
                </div>
                <div class="skill-effect">
                  <strong>技能效果：</strong>${skillEffect || '暂无效果说明'}
                </div>
              </div>
            </div>
          `;
        }
      }

      // 更新技能数量显示
      const skillCountElement = document.querySelector('.passive-skills-title .skill-count');
      if (skillCountElement) {
        skillCountElement.textContent = `${skillCount}个技能`;
      }

      passiveSkillsGrid.innerHTML = passiveSkillsHTML || '<div style="text-align: center; color: #666;">暂无被动技能</div>';
    }

    // 更新身体部位
    function updateCombatBodyParts(statData) {
      const bodyPartsGrid = document.getElementById('combat-body-parts-grid');
      const bodyParts = GetRawValue(statData, '身体部位', {});
      const gender = SafeGetValue(statData, '基础档案.性别', '男性');

      let bodyPartsHTML = '';

      // 根据性别显示不同的身体部位
      const bodyPartKeys = ['胸部', '菊穴', '脚部'];
      if (gender === '女性') {
        bodyPartKeys.splice(1, 0, '小穴');
      } else if (gender === '男性') {
        bodyPartKeys.splice(1, 0, '肉棒');
      } else if (gender === '扶他') {
        bodyPartKeys.splice(1, 0, '肉棒', '小穴');
      }

      for (const partKey of bodyPartKeys) {
        const partData = bodyParts[partKey];
        if (!partData) continue;

        let partInfo = '';
        let partDescription = '';
        const partName = partKey;

        if (partKey === '胸部') {
          const size = SafeGetValue(partData, '大小', 'N/A');
          const sensitivity = SafeGetValue(partData, '敏感度', 'N/A');
          const status = SafeGetValue(partData, '状态', 'N/A');
          partInfo = `${size} | 敏感度:${sensitivity} | ${status}`;
          partDescription = SafeGetValue(partData, '描述', '');
        } else if (partKey === '肉棒') {
          const length = SafeGetValue(partData, '长度', 'N/A');
          const thickness = SafeGetValue(partData, '粗细', 'N/A');
          const sensitivity = SafeGetValue(partData, '敏感度', 'N/A');
          const status = SafeGetValue(partData, '状态', 'N/A');
          partInfo = `${length} | ${thickness} | 敏感度:${sensitivity} | ${status}`;
          partDescription = SafeGetValue(partData, '描述', '');
        } else if (partKey === '小穴') {
          const tightness = SafeGetValue(partData, '紧致度', 'N/A');
          const wetness = SafeGetValue(partData, '湿润度', 'N/A');
          const sensitivity = SafeGetValue(partData, '敏感度', 'N/A');
          const status = SafeGetValue(partData, '状态', 'N/A');
          partInfo = `${tightness} | 湿润度:${wetness} | 敏感度:${sensitivity} | ${status}`;
          partDescription = SafeGetValue(partData, '描述', '');
        } else if (partKey === '菊穴') {
          const tightness = SafeGetValue(partData, '紧致度', 'N/A');
          const sensitivity = SafeGetValue(partData, '敏感度', 'N/A');
          const status = SafeGetValue(partData, '状态', 'N/A');
          partInfo = `${tightness} | 敏感度:${sensitivity} | ${status}`;
          partDescription = SafeGetValue(partData, '描述', '');
        } else if (partKey === '脚部') {
          const size = SafeGetValue(partData, '大小', 'N/A');
          const sensitivity = SafeGetValue(partData, '敏感度', 'N/A');
          const status = SafeGetValue(partData, '状态', 'N/A');
          partInfo = `${size} | 敏感度:${sensitivity} | ${status}`;
          partDescription = SafeGetValue(partData, '描述', '');
        }

        bodyPartsHTML += `
          <div class="inventory-item" data-part="${partName}" onclick="toggleItemDetails(this)">
            <div class="item-header">
              <div class="item-name">${partName}</div>
              <div class="item-type">${partInfo}</div>
              <div class="expand-icon">▼</div>
            </div>
            <div class="item-details" style="display: none;">
              <div class="item-description">
                <strong>部位描述：</strong>${partDescription || '暂无描述'}
              </div>
            </div>
          </div>
        `;
      }

      bodyPartsGrid.innerHTML = bodyPartsHTML || '<div style="text-align: center; color: #666;">暂无身体部位信息</div>';
    }

    // 更新背包物品
    function updateCombatInventory(statData) {
      const inventoryGrid = document.getElementById('combat-inventory-grid');
      const items = GetRawValue(statData, '装备与物品.持有物品', {});

      let inventoryHTML = '';

      for (const itemKey in items) {
        if (itemKey === '$meta') continue;

        const item = items[itemKey];
        const itemName = SafeGetValue(item, '名称', '');
        const itemType = SafeGetValue(item, '类型', '');
        const itemQuantity = SafeGetValue(item, '数量', '1');
        const itemDescription = SafeGetValue(item, '描述', '');
        const itemEffect = SafeGetValue(item, '效果', '');

        if (itemName && itemName !== 'N/A') {
          inventoryHTML += `
            <div class="inventory-item" data-item="${itemName}" onclick="toggleItemDetails(this)">
              <div class="item-header">
                <div class="item-name">${itemName}</div>
                <div class="item-type">${itemType}</div>
                <div class="item-quantity">x${itemQuantity}</div>
                <div class="expand-icon">▼</div>
              </div>
              <div class="item-details" style="display: none;">
                <div class="item-description">
                  <strong>物品描述：</strong>${itemDescription || '暂无描述'}
                </div>
                <div class="item-effect">
                  <strong>使用效果：</strong>${itemEffect || '暂无效果说明'}
                </div>
                <button class="use-item-button" onclick="useItem('${itemName}')">使用物品</button>
              </div>
            </div>
          `;
        }
      }

      inventoryGrid.innerHTML = inventoryHTML || '<div style="text-align: center; color: #666;">背包为空</div>';
    }

    // 更新战斗记录
    function updateCombatLog(statData) {
      const combatLog = document.getElementById('combat-log');
      const battleRecords = GetRawValue(statData, '性斗系统.战斗记录', {});

      let logHTML = '';

      for (const recordKey in battleRecords) {
        if (recordKey === '$meta') continue;

        const record = battleRecords[recordKey];
        const recordText = SafeGetValue(record, '内容', '');
        const recordType = SafeGetValue(record, '类型', 'system');

        if (recordText && recordText !== 'N/A') {
          logHTML += `
            <div class="combat-log-entry ${recordType}-message">
              ${recordText}
            </div>
          `;
        }
      }

      combatLog.innerHTML = logHTML || '<div style="text-align: center; color: #666;">战斗尚未开始</div>';

      // 滚动到底部
      combatLog.scrollTop = combatLog.scrollHeight;
    }

    // 技能详情切换
    function toggleSkillDetails(element) {
      const details = element.querySelector('.skill-details');
      const icon = element.querySelector('.expand-icon');

      if (details.style.display === 'none') {
        details.style.display = 'block';
        icon.textContent = '▲';
      } else {
        details.style.display = 'none';
        icon.textContent = '▼';
      }
    }

    // 物品详情切换
    function toggleItemDetails(element) {
      const details = element.querySelector('.item-details');
      const icon = element.querySelector('.expand-icon');

      if (details.style.display === 'none') {
        details.style.display = 'block';
        icon.textContent = '▲';
      } else {
        details.style.display = 'none';
        icon.textContent = '▼';
      }
    }

    // 使用技能
    function useSkill(skillName) {
      console.log(`使用技能: ${skillName}`);
      // 发送技能使用消息给AI
      triggerSlash(`/send 使用技能：${skillName}`);

      // 添加战斗记录
      addCombatLogEntry('player-action', `【技能使用】星耀使用了${skillName}！`);
    }

    // 使用物品
    function useItem(itemName) {
      console.log(`使用物品: ${itemName}`);
      // 发送物品使用消息给AI
      triggerSlash(`/send 使用物品：${itemName}`);

      // 添加战斗记录
      addCombatLogEntry('player-action', `【物品使用】星耀使用了${itemName}！`);
    }

    // 添加战斗记录
    function addCombatLogEntry(type, message) {
      const combatLog = document.getElementById('combat-log');
      const entry = document.createElement('div');
      entry.className = `combat-log-entry ${type}`;
      entry.textContent = message;
      combatLog.appendChild(entry);
      combatLog.scrollTop = combatLog.scrollHeight;
    }
  </script>
</body>

</html>
