    }

    #copy-button {
      background-color: var(--accent-color);
    }

    #copy-button:hover {
      background-color: var(--accent-color-dark);
    }

    #copy-success-msg {
      text-align: center;
      color: var(--accent-color);
      margin-top: 15px;
      font-weight: 500;
      opacity: 0;
      transition: opacity 0.3s;
    }

    /* 移动端适配 */
    @media (max-width: 768px) {
      body {
        padding: 12px;
      }

      .container {
        padding: 20px;
      }

      .stat-item {
        flex-direction: column;
        align-items: center;
        gap: 12px;
        text-align: center;
      }

      .stat-controls {
        align-items: center;
        width: 100%;
      }

      .stat-buttons {
        justify-content: center;
        gap: 8px;
        flex-wrap: wrap;
      }

      .stat-button {
        width: 35px;
        height: 35px;
        font-size: 12px;
      }

      .stat-description {
        text-align: center;
      }

      .grid-2 {
        grid-template-columns: 1fr;
        gap: 15px;
      }

      .grid-3 {
        grid-template-columns: 1fr;
        gap: 10px;
      }

      .selection-grid {
        grid-template-columns: 1fr;
        gap: 10px;
      }

      .tab-navigation {
        flex-direction: column;
        gap: 5px;
      }

      .tab-nav-item {
        padding: 10px 0;
      }
    }
  </style>
</head>

<body>
  <div class="container" id="main-container">

    <div id="creation-form">
      <h1 class="page-title">自定义开局</h1>

      <div class="tab-navigation">
        <div class="tab-nav-item active" data-page="page-1">1. 基础档案</div>
        <div class="tab-nav-item" data-page="page-2">2. 属性分配</div>
        <div class="tab-nav-item" data-page="page-3">3. 技能与特质</div>
      </div>

      <!-- Page 1: 基础档案 -->
      <div id="page-1" class="page active">
        <h2>Step 1: 设定你的基础档案</h2>

        <div class="form-group">
          <label for="student-name">你的名字</label>
          <input type="text" id="student-name" placeholder="输入你的名字">
        </div>

        <div class="grid-2">
          <div class="form-group">
            <label for="student-gender">你的性别</label>
            <select id="student-gender">
              <option value="男性">男性</option>
              <option value="女性">女性</option>
              <option value="扶他">扶他</option>
            </select>
          </div>
          <div class="form-group">
            <label for="difficulty">游戏难度</label>
            <select id="difficulty">
              <option value="简单">简单 (200属性点)</option>
              <option value="普通">普通 (150属性点)</option>
              <option value="困难">困难 (100属性点)</option>
              <option value="地狱">地狱 (50属性点)</option>
            </select>
            <div class="description-box" style="margin-top: 8px; font-size: 0.85em;">
              难度越高，获得的属性点越少，但可能获得特殊奖励。
            </div>
          </div>
        </div>

        <div class="form-group">
          <label for="student-personality">性格关键词 (以逗号分隔)</label>
          <input type="text" id="student-personality" placeholder="例如: 自信, 害羞, 冷静, 冲动, 温柔">
        </div>

        <div class="form-group">
          <label for="student-background">入学背景：选择或自定义你进入学园的原因</label>
          <select id="student-background">
            <option value="天赋异禀的新生">天赋异禀的新生 (潜力无限)</option>
            <option value="转校生">转校生 (寻求新的开始)</option>
            <option value="特招生">特招生 (特殊能力者)</option>
            <option value="复读生">复读生 (重新挑战)</option>
            <option value="贵族子弟">贵族子弟 (家族期望)</option>
            <option value="平民天才">平民天才 (逆袭之路)</option>
            <option value="custom">自定义背景...</option>
          </select>
          <div id="background-description" class="description-box"></div>
          <input type="text" id="student-background-custom" placeholder="如：我是一名被家族安排来学园学习的贵族子弟..."
            style="display:none; margin-top:10px;">
        </div>

        <div class="form-group">
          <label for="student-appearance">外貌描述</label>
          <textarea id="student-appearance" placeholder="详细描述你的外貌特征。例如：黑色短发，左眼有伤疤，身材高挑，穿着学园制服..."></textarea>
        </div>

        <div class="form-group">
          <label for="student-details">更多细节补充 (过往、特殊能力等)</label>
          <textarea id="student-details" placeholder="任何你想让AI知道的角色设定都可以在这里补充。例如：擅长格斗，性格内向，有特殊血统..."></textarea>
        </div>
      </div>

      <!-- Page 2: 属性分配 -->
      <div id="page-2" class="page">
        <h2>Step 2: 分配你的属性点</h2>

        <div class="stats-container">
          <div class="stats-header">
            <h3 style="margin: 0; color: var(--accent-color-dark);">属性分配</h3>
            <div class="points-display" id="points-display">200 点</div>
          </div>

          <div class="stat-item">
            <div class="stat-name">等级</div>
            <div class="stat-controls">
              <div class="stat-value" id="level-value">1</div>
              <div class="stat-buttons">
                <button class="stat-button" onclick="changeStat('level', -1)">-</button>
                <button class="stat-button" onclick="changeStat('level', 1)">+</button>
              </div>
            </div>
          </div>

          <div class="stat-item">
            <div class="stat-name">潜力</div>
            <div class="stat-controls">
              <div class="stat-value" id="potential-value">7.0</div>
              <div class="stat-buttons">
                <button class="stat-button" onclick="changeStat('potential', -0.5)">-0.5</button>
                <button class="stat-button" onclick="changeStat('potential', -0.1)">-0.1</button>
                <button class="stat-button" onclick="changeStat('potential', 0.1)">+0.1</button>
                <button class="stat-button" onclick="changeStat('potential', 0.5)">+0.5</button>
              </div>
            </div>
          </div>

          <div class="stat-item">
            <div class="stat-name">体力</div>
            <div class="stat-controls">
              <div class="stat-value" id="stamina-value">10</div>
              <div class="stat-buttons">
                <button class="stat-button" onclick="changeStat('stamina', -5)">-5</button>
                <button class="stat-button" onclick="changeStat('stamina', -1)">-</button>
                <button class="stat-button" onclick="changeStat('stamina', 1)">+</button>
                <button class="stat-button" onclick="changeStat('stamina', 5)">+5</button>
              </div>
            </div>
          </div>

          <div class="stat-item">
            <div class="stat-name">魅力</div>
            <div class="stat-controls">
              <div class="stat-value" id="charm-value">10</div>
              <div class="stat-buttons">
                <button class="stat-button" onclick="changeStat('charm', -5)">-5</button>
                <button class="stat-button" onclick="changeStat('charm', -1)">-</button>
                <button class="stat-button" onclick="changeStat('charm', 1)">+</button>
                <button class="stat-button" onclick="changeStat('charm', 5)">+5</button>
              </div>
            </div>
          </div>

          <div class="stat-item">
            <div class="stat-name">幸运值</div>
            <div class="stat-controls">
              <div class="stat-value" id="luck-value">10</div>
              <div class="stat-buttons">
                <button class="stat-button" onclick="changeStat('luck', -5)">-5</button>
                <button class="stat-button" onclick="changeStat('luck', -1)">-</button>
                <button class="stat-button" onclick="changeStat('luck', 1)">+</button>
                <button class="stat-button" onclick="changeStat('luck', 5)">+5</button>
              </div>
            </div>
          </div>

          <div class="stat-item">
            <div class="stat-name">忍耐力</div>
            <div class="stat-controls">
              <div class="stat-value" id="endurance-value">56</div>
              <div class="stat-description">
                <small>根据等级自动计算</small>
              </div>
            </div>
          </div>

          <div class="stat-item">
            <div class="stat-name">性斗力</div>
            <div class="stat-controls">
              <div class="stat-value" id="combat-value">14</div>
              <div class="stat-description">
                <small>根据等级和潜力自动计算</small>
              </div>
            </div>
          </div>
        </div>

        <div class="description-box">
          <strong>属性说明：</strong><br>
          • <strong>等级</strong>：影响性斗力和忍耐力的基础计算，范围1-20级<br>
          • <strong>潜力</strong>：影响所有计算属性的成长系数，范围5.0-10.0<br>
          • <strong>体力</strong>：影响你的生命值和体力恢复速度<br>
          • <strong>魅力</strong>：影响他人对你的初始好感度<br>
          • <strong>幸运值</strong>：影响随机事件和稀有物品掉落<br>
          • <strong>忍耐力</strong>：影响你对快感攻击的抗性，计算公式：(等级 × 潜力 × 0.8) + 装备加成 + 基础值50<br>
          • <strong>性斗力</strong>：根据等级和潜力自动计算，计算公式：(等级 × 潜力) + 装备加成 + 基础值7
        </div>
      </div>

      <!-- Page 3: 技能与特质 -->
      <div id="page-3" class="page">
        <h2>Step 3: 选择你的技能与特质</h2>

        <div class="form-group">
          <label>初始技能 (选择2个)</label>
          <div class="selection-grid" id="skills-grid">
            <div class="selection-item" data-skill="快感冲击">
              <h4>快感冲击</h4>
              <p>基础攻击技能，造成快感伤害</p>
            </div>
            <div class="selection-item" data-skill="精神防护">
              <h4>精神防护</h4>
              <p>提升忍耐力，减少快感伤害</p>
            </div>
            <div class="selection-item" data-skill="魅惑术">
              <h4>魅惑术</h4>
              <p>降低对手的防御力</p>
            </div>
            <div class="selection-item" data-skill="体力恢复">
              <h4>体力恢复</h4>
              <p>快速恢复体力值</p>
            </div>
            <div class="selection-item" data-skill="幸运一击">
              <h4>幸运一击</h4>
              <p>有概率造成额外伤害</p>
            </div>
            <div class="selection-item" data-skill="心灵感应">
              <h4>心灵感应</h4>
              <p>感知对手的状态和意图</p>
            </div>
            <div class="selection-item" data-skill="custom">
              <h4>自定义技能</h4>
              <p>输入你想要的技能名称和效果</p>
            </div>
          </div>
          <input type="text" id="custom-skill-input" placeholder="输入自定义技能名称和效果，如：火焰冲击 - 造成火属性快感伤害"
            style="display:none; margin-top:10px;">
        </div>

        <div class="form-group">
          <label>性癖倾向 (选择1个)</label>
          <div class="selection-grid" id="kinks-grid">
            <div class="selection-item" data-kink="支配倾向">
              <h4>支配倾向</h4>
              <p>喜欢控制和主导他人</p>
            </div>
            <div class="selection-item" data-kink="服从倾向">
              <h4>服从倾向</h4>
              <p>享受被控制和引导</p>
            </div>
            <div class="selection-item" data-kink="观察者">
              <h4>观察者</h4>
              <p>喜欢观察和分析他人</p>
            </div>
            <div class="selection-item" data-kink="均衡型">
              <h4>均衡型</h4>
              <p>根据情况灵活调整</p>
            </div>
            <div class="selection-item" data-kink="custom">
              <h4>自定义倾向</h4>
              <p>输入你独特的性癖倾向</p>
            </div>
          </div>
          <input type="text" id="custom-kink-input" placeholder="输入自定义性癖倾向，如：温柔调教型"
            style="display:none; margin-top:10px;">
        </div>

        <div class="form-group">
          <label>永久状态 (选择1个，可选)</label>
          <div class="selection-grid" id="permanent-status-grid">
            <div class="selection-item" data-status="无">
              <h4>无</h4>
              <p>保持纯净状态</p>
            </div>
            <div class="selection-item" data-status="敏感体质">
              <h4>敏感体质</h4>
              <p>对快感更加敏感，但恢复更快</p>
            </div>
            <div class="selection-item" data-status="冷静头脑">
              <h4>冷静头脑</h4>
              <p>不容易被情绪影响，但缺乏激情</p>
            </div>
            <div class="selection-item" data-status="魅力光环">
              <h4>魅力光环</h4>
              <p>天然具有吸引他人的魅力</p>
            </div>
            <div class="selection-item" data-status="custom">
              <h4>自定义状态</h4>
              <p>输入你想要的特殊永久状态</p>
            </div>
          </div>
          <input type="text" id="custom-status-input" placeholder="输入自定义永久状态，如：龙族血统"
            style="display:none; margin-top:10px;">
        </div>
      </div>

      <div class="navigation-buttons">
        <button id="prev-button" disabled>上一页</button>
        <button id="next-button">下一页</button>
        <button id="send-button" style="display: none;">开始学园生活</button>
      </div>
    </div>
  </div>

  <!-- Modal -->
  <div id="command-modal" class="modal-overlay">
    <div class="modal-content">
      <h3>学园指令已生成</h3>
      <p style="text-align: center; color: var(--text-muted-color);">请复制下方的全部内容，并在新的对话中发送，以正式开始你的学园生活。</p>
      <div id="modal-command-box"></div>
      <div class="modal-actions">
        <button id="copy-button">复制指令并关闭</button>
      </div>
      <p id="copy-success-msg">已成功复制到剪贴板！</p>
    </div>
  </div>


  <script>
    const pages = document.querySelectorAll('.page');
    const navItems = document.querySelectorAll('.tab-nav-item');
    const prevButton = document.getElementById('prev-button');
    const nextButton = document.getElementById('next-button');
    const sendButton = document.getElementById('send-button');
    let currentPage = 0;

    // 属性点系统
    let availablePoints = 200; // 减少总点数
    let stats = {
      level: 1, // 新增等级
      potential: 7.0, // 新增潜力
      stamina: 10,
      endurance: 10,
      charm: 10,
      luck: 10
    };

    // 计算性斗力（根据等级和潜力动态计算）
    function calculateCombatPower() {
      const level = stats.level;
      const potential = stats.potential;
      const baseCombat = 7; // 基础性斗力

      // 性斗力 = (等级 × 潜力) + 装备加成 + 基础值7
      // 这里装备加成为0，所以简化为：等级 × 潜力 + 基础值7
      return Math.floor(level * potential + baseCombat);
    }

    // 计算忍耐力（根据等级和潜力动态计算）
    function calculateEndurance() {
      const level = stats.level;
      const potential = stats.potential;
      const baseEndurance = 50;

      // 忍耐力 = (等级 × 潜力 × 0.8) + 装备加成 + 基础值50
      return Math.floor(level * potential * 0.8 + baseEndurance);
    }

    const difficultyPoints = {
      '简单': 200,
      '普通': 150,
      '困难': 100,
      '地狱': 50
    };

    // 技能和特质选择
    let selectedSkills = [];
    let selectedKink = null;
    let selectedStatus = '无';

    const backgroundData = {
      "天赋异禀的新生": "你天生就拥有出色的性斗天赋，在入学测试中表现优异，被学园特别关注。你的潜力无限，但也面临着更大的挑战和期望。学园希望你能成为未来的性斗之星，但这条路并不容易。",
      "转校生": "你从其他学园转学而来，带着不同的经历和技能。在新的环境中，你需要重新适应学园的文化和规则，同时也要证明自己的实力。你的过去可能隐藏着不为人知的秘密。",
      "特招生": "你因为特殊的能力或背景被学园特招入学。可能是某个重要人物的推荐，或者是你在某个领域展现出的非凡才能。学园对你寄予厚望，但也意味着你要承担更多的责任。",
      "复读生": "你曾经是学园的学生，但因为某些原因离开了。现在你重新回到学园，带着过去的经验和教训。你比新生更了解学园的规则，但也面临着重新证明自己的挑战。",
      "贵族子弟": "你来自显赫的贵族家庭，被家族安排来学园学习。你享受着优渥的生活条件，但也承受着家族期望的压力。你的每一个行动都可能影响到家族的声誉。",
      "平民天才": "你来自普通家庭，凭借自己的努力和天赋获得了入学机会。你比其他人更加珍惜这个机会，但也面临着来自贵族学生的歧视和挑战。",
      "custom": "你的故事，由你来书写。你将以完全自定义的身份，踏入这座命运的学园。"
    };

    function setupCustomInput(selectId, customInputId) {
      const selectElement = document.getElementById(selectId);
      const customInputElement = document.getElementById(customInputId);
      if (selectElement && customInputElement) {
        selectElement.addEventListener('change', function () {
          customInputElement.style.display = this.value === 'custom' ? 'block' : 'none';
        });
      }
    }

    setupCustomInput('student-background', 'student-background-custom');

    const backgroundSelect = document.getElementById('student-background');
    const backgroundDesc = document.getElementById('background-description');
    const customBackgroundInput = document.getElementById('student-background-custom');

    function updateBackground() {
      if (backgroundSelect) {
        const selected = backgroundSelect.value;
        if (backgroundDesc) backgroundDesc.innerHTML = `<strong>背景描述:</strong><br>${backgroundData[selected]}`;
        if (customBackgroundInput) customBackgroundInput.style.display = selected === 'custom' ? 'block' : 'none';
      }
    }

    // 难度变化处理
    const difficultySelect = document.getElementById('difficulty');
    difficultySelect.addEventListener('change', function () {
      const newPoints = difficultyPoints[this.value];
      const currentUsed = Object.values(stats).reduce((sum, val) => sum + val, 0) - 50;
      availablePoints = newPoints - currentUsed;
      updatePointsDisplay();
      updateStatButtons();
    });

    function changeStat(statName, change) {
      if (change > 0 && availablePoints < change) return;
      if (change < 0 && stats[statName] <= Math.abs(change)) return;

      // 检查上限
      const newValue = stats[statName] + change;
      if (statName === 'charm' || statName === 'luck') {
        if (newValue > 100) return;
      }
      if (statName === 'level') {
        if (newValue < 1 || newValue > 20) return; // 等级限制1-20
      }
      if (statName === 'potential') {
        if (newValue < 5.0 || newValue > 10.0) return; // 潜力限制5.0-10.0
      }

      stats[statName] = newValue;
      availablePoints -= change;

      // 潜力值显示一位小数
      if (statName === 'potential') {
        document.getElementById(statName + '-value').textContent = stats[statName].toFixed(1);
      } else {
        document.getElementById(statName + '-value').textContent = stats[statName];
      }

      updatePointsDisplay();
      updateStatButtons();
      updateCombatPower(); // 更新性斗力显示
      updateEndurance(); // 更新忍耐力显示
    }

    function updateCombatPower() {
      const combatPower = calculateCombatPower();
      document.getElementById('combat-value').textContent = combatPower;
    }

    function updateEndurance() {
      const endurance = calculateEndurance();
      document.getElementById('endurance-value').textContent = endurance;
    }

    function updatePointsDisplay() {
      document.getElementById('points-display').textContent = availablePoints + ' 点';
    }

    function updateStatButtons() {
      Object.keys(stats).forEach(stat => {
        // 跳过性斗力和忍耐力，因为它们不能手动调整
        if (stat === 'combat' || stat === 'endurance') return;

        const minusBtn = document.querySelector(`[onclick="changeStat('${stat}', -1)"]`);
        const plusBtn = document.querySelector(`[onclick="changeStat('${stat}', 1)"]`);
        const minus5Btn = document.querySelector(`[onclick="changeStat('${stat}', -5)"]`);
        const plus5Btn = document.querySelector(`[onclick="changeStat('${stat}', 5)"]`);
        const minus01Btn = document.querySelector(`[onclick="changeStat('${stat}', -0.1)"]`);
        const plus01Btn = document.querySelector(`[onclick="changeStat('${stat}', 0.1)"]`);
        const minus05Btn = document.querySelector(`[onclick="changeStat('${stat}', -0.5)"]`);
        const plus05Btn = document.querySelector(`[onclick="changeStat('${stat}', 0.5)"]`);

        // 检查上限
        const isAtMax = (stat === 'charm' || stat === 'luck') ? stats[stat] >= 100 : false;
        const isLevelMax = stat === 'level' ? stats[stat] >= 20 : false;
        const isLevelMin = stat === 'level' ? stats[stat] <= 1 : false;
        const isPotentialMax = stat === 'potential' ? stats[stat] >= 10.0 : false;
        const isPotentialMin = stat === 'potential' ? stats[stat] <= 5.0 : false;

        if (minusBtn) minusBtn.disabled = stats[stat] <= 1 || isLevelMin;
        if (plusBtn) plusBtn.disabled = availablePoints <= 0 || isAtMax || isLevelMax;
        if (minus5Btn) minus5Btn.disabled = stats[stat] <= 5 || (stat === 'level' && stats[stat] <= 1);
        if (plus5Btn) plus5Btn.disabled = availablePoints < 5 || isAtMax || (stat === 'level' && stats[stat] >= 20);

        // 潜力按钮
        if (minus01Btn) minus01Btn.disabled = stats[stat] <= 5.0 || isPotentialMin;
        if (plus01Btn) plus01Btn.disabled = availablePoints <= 0 || isPotentialMax;
        if (minus05Btn) minus05Btn.disabled = stats[stat] <= 5.0 || isPotentialMin;
        if (plus05Btn) plus05Btn.disabled = availablePoints < 0.5 || isPotentialMax;
      });
    }

    // 技能选择
    document.getElementById('skills-grid').addEventListener('click', function (e) {
      const item = e.target.closest('.selection-item');
      if (!item) return;

      const skill = item.dataset.skill;
      if (selectedSkills.includes(skill)) {
        selectedSkills = selectedSkills.filter(s => s !== skill);
        item.classList.remove('selected');
      } else if (selectedSkills.length < 2) {
        selectedSkills.push(skill);
        item.classList.add('selected');
      }

      // 处理自定义技能输入框显示
      const customInput = document.getElementById('custom-skill-input');
      if (skill === 'custom') {
        customInput.style.display = 'block';
      } else {
        customInput.style.display = 'none';
      }
    });

    // 性癖选择
    document.getElementById('kinks-grid').addEventListener('click', function (e) {
      const item = e.target.closest('.selection-item');
      if (!item) return;

      document.querySelectorAll('#kinks-grid .selection-item').forEach(el => el.classList.remove('selected'));
      item.classList.add('selected');
      selectedKink = item.dataset.kink;

      // 处理自定义性癖输入框显示
      const customInput = document.getElementById('custom-kink-input');
      if (selectedKink === 'custom') {
        customInput.style.display = 'block';
      } else {
        customInput.style.display = 'none';
      }
    });

    // 永久状态选择
    document.getElementById('permanent-status-grid').addEventListener('click', function (e) {
      const item = e.target.closest('.selection-item');
      if (!item) return;

      document.querySelectorAll('#permanent-status-grid .selection-item').forEach(el => el.classList.remove('selected'));
      item.classList.add('selected');
      selectedStatus = item.dataset.status;

      // 处理自定义状态输入框显示
      const customInput = document.getElementById('custom-status-input');
      if (selectedStatus === 'custom') {
        customInput.style.display = 'block';
      } else {
        customInput.style.display = 'none';
      }
    });

    function showPage(pageIndex) {
      pages.forEach((page, index) => {
        if (page) page.classList.toggle('active', index === pageIndex);
      });
      navItems.forEach((nav, index) => {
        if (nav) nav.classList.toggle('active', index === pageIndex);
      });

      if (prevButton) prevButton.disabled = pageIndex === 0;
      if (nextButton) nextButton.style.display = pageIndex === pages.length - 1 ? 'none' : 'inline-block';
      if (sendButton) sendButton.style.display = pageIndex === pages.length - 1 ? 'inline-block' : 'none';
      currentPage = pageIndex;
    }

    navItems.forEach((nav, index) => {
      if (nav) nav.addEventListener('click', () => showPage(index));
    });

    if (prevButton) prevButton.addEventListener('click', () => { if (currentPage > 0) showPage(currentPage - 1); });
    if (nextButton) nextButton.addEventListener('click', () => { if (currentPage < pages.length - 1) showPage(currentPage + 1); });

    // Modal logic
    const modal = document.getElementById('command-modal');
    const modalCommandBox = document.getElementById('modal-command-box');
    const copyButton = document.getElementById('copy-button');
    const copySuccessMsg = document.getElementById('copy-success-msg');

    if (sendButton) sendButton.addEventListener('click', () => {
      const getCustomizableValue = (selectId, customId) => {
        const select = document.getElementById(selectId);
        return select.value === 'custom' ? document.getElementById(customId).value : select.value;
      };

      const backgroundValueRaw = backgroundSelect.value;
      const backgroundValue = backgroundValueRaw === 'custom' ? document.getElementById('student-background-custom').value : backgroundValueRaw;

      // 处理自定义选项
      let finalSkills = selectedSkills.map(skill => {
        if (skill === 'custom') {
          const customSkill = document.getElementById('custom-skill-input').value;
          return customSkill || '自定义技能';
        }
        return skill;
      });

      let finalKink = selectedKink;
      if (selectedKink === 'custom') {
        const customKink = document.getElementById('custom-kink-input').value;
        finalKink = customKink || '自定义倾向';
      }

      let finalStatus = selectedStatus;
      if (selectedStatus === 'custom') {
        const customStatus = document.getElementById('custom-status-input').value;
        finalStatus = customStatus || '自定义状态';
      }

      const messageForAI = `> **[ 系统指令：学园新生注册协议启动 ]**
> **当前时间点**：新生入学第一天，步入天海高等性斗学园
>
> ---
> **【1. 新生档案】**
> - **姓名**: ${document.getElementById('student-name').value || '未命名'}
> - **性别**: ${document.getElementById('student-gender').value}
> - **性格关键词**: ${document.getElementById('student-personality').value || '未指定'}
> - **入学背景**: ${backgroundValue}
> - **外貌描述**: ${document.getElementById('student-appearance').value || '由AI自由发挥'}
> - **补充设定**: ${document.getElementById('student-details').value || "无"}
>
> ---
> **【2. 游戏难度与属性】**
> - **难度等级**: ${document.getElementById('difficulty').value}
> - **等级**: ${stats.level}
> - **潜力**: ${stats.potential.toFixed(1)}
> - **体力**: ${stats.stamina}
> - **忍耐力**: ${calculateEndurance()}
> - **性斗力**: ${calculateCombatPower()}
> - **魅力**: ${stats.charm}
> - **幸运值**: ${stats.luck}
>
> ---
> **【3. 技能与特质】**
> - **初始技能**: ${finalSkills.join(', ') || '无'}
> - **性癖倾向**: ${finalKink || '未选择'}
> - **永久状态**: ${finalStatus}
>
> ---
> **【4. AI核心任务 (强制执行)】**
> 1. 根据上述档案，在叙事中开始{{user}}作为新生的故事。描绘{{user}}作为【新生】出现在学园里的场景与心理状态。
> 2. 根据属性分配和技能选择，为新生设定相应的初始状态和能力。
> 3. 根据性癖倾向和永久状态，为新生设定相应的性格特征和特殊能力。
> 4. 最后，在你的回复 **最末尾**，检测并进行变量更新。`;

      if (modalCommandBox) modalCommandBox.textContent = messageForAI.trim();
      if (modal) modal.classList.add('show');
    });

    if (copyButton) copyButton.addEventListener('click', () => {
      navigator.clipboard.writeText(modalCommandBox.textContent).then(() => {
        if (copySuccessMsg) copySuccessMsg.style.opacity = '1';
        setTimeout(() => {
          if (modal) modal.classList.remove('show');
          if (copySuccessMsg) copySuccessMsg.style.opacity = '0';
          const creationForm = document.getElementById('creation-form');
          if (creationForm) creationForm.innerHTML = '<h1 class="page-title">指令已复制，请在新的对话中发送以开启你的学园生活。</h1>';
        }, 1500);
      }).catch(err => {
        console.error('复制失败: ', err);
        alert('复制失败，请手动复制。');
      });
    });

    if (modal) modal.addEventListener('click', (event) => {
      if (event.target === modal) {
        modal.classList.remove('show');
      }
    });

    // Initialize
    updateBackground();
    if (backgroundSelect) backgroundSelect.addEventListener('change', updateBackground);
    showPage(0);
    updatePointsDisplay();
    updateStatButtons();
    updateCombatPower(); // 初始化性斗力显示
    updateEndurance(); // 初始化忍耐力显示
    // 初始化潜力值显示
    document.getElementById('potential-value').textContent = stats.potential.toFixed(1);
  </script>
</body>

</html>
