      padding: 8px 12px;
      background: rgba(0, 0, 0, 0.2);
      border-radius: var(--border-radius);
      margin: 5px 0;
      border: 1px solid rgba(255, 255, 255, 0.1);
    }

    .equipment-name {
      color: var(--text-primary);
      font-weight: 600;
    }

    .equipment-level {
      color: var(--accent-warning);
      font-weight: 700;
      font-size: var(--font-size-sm);
    }

    /* Modal Styles */
    .upgrade-modal {
      display: none;
      position: fixed;
      z-index: 100;
      left: 0;
      top: 0;
      width: 100%;
      height: 100%;
      overflow: auto;
      background-color: rgba(0, 0, 0, 0.7);
      color: #FFF;
    }

    .interaction-modal-content {
      background-color: #2c2c2e;
      margin: 5% auto;
      padding: 20px;
      border: 2px solid var(--border-highlight);
      width: 80%;
      max-width: 600px;
      position: relative;
      font-family: var(--font-family);
      color: #FFFFFF;
    }

    .upgrade-modal-close {
      color: var(--text-secondary);
      float: right;
      font-size: 28px;
      font-weight: bold;
      cursor: pointer;
    }

    .upgrade-modal-close:hover,
    .upgrade-modal-close:focus {
      color: var(--text-header);
    }

    .upgrade-section {
      margin-bottom: 20px;
      padding-bottom: 15px;
      border-bottom: 1px solid var(--border-color);
    }

    .upgrade-section:last-child {
      border-bottom: none;
    }

    .upgrade-section h3 {
      font-family: 'Orbitron', sans-serif;
      letter-spacing: 1px;
      text-transform: uppercase;
      font-size: 1.1em;
      border-bottom: 1px solid var(--border-color);
      padding-bottom: 10px;
    }

    .interaction-doll-list {
      display: flex;
      flex-wrap: wrap;
      gap: 10px;
      padding-top: 10px;
      margin-bottom: 20px;
    }

    .interaction-doll-item {
      border: 1px solid var(--border-color, #4a4a4a);
      padding: 8px 15px;
      cursor: pointer;
      transition: background-color 0.2s, color 0.2s;
      border-radius: var(--border-radius, 0);
      user-select: none;
      color: var(--text-primary, #f4e4bc);
    }

    .interaction-doll-item:hover {
      background-color: var(--border-color, #4a4a4a);
      color: var(--text-header, #ffd700);
    }

    .interaction-doll-item.selected {
      background-color: var(--accent-highlight, #cd853f);
      color: var(--bg-color, #2c1810) !important;
      border-color: var(--accent-highlight, #cd853f);
      font-weight: bold;
