          const length = SafeGetValue(partData, '长度', 'N/A');
          const thickness = SafeGetValue(partData, '粗细', 'N/A');
          const sensitivity = SafeGetValue(partData, '敏感度', 'N/A');
          const status = SafeGetValue(partData, '状态', 'N/A');
          partInfo = `${length} | ${thickness} | 敏感度:${sensitivity} | ${status}`;
          partDescription = SafeGetValue(partData, '描述', '');
        } else if (partKey === '小穴') {
          const tightness = SafeGetValue(partData, '紧致度', 'N/A');
          const wetness = SafeGetValue(partData, '湿润度', 'N/A');
          const sensitivity = SafeGetValue(partData, '敏感度', 'N/A');
          const status = SafeGetValue(partData, '状态', 'N/A');
          partInfo = `${tightness} | 湿润度:${wetness} | 敏感度:${sensitivity} | ${status}`;
          partDescription = SafeGetValue(partData, '描述', '');
        } else if (partKey === '菊穴') {
          const tightness = SafeGetValue(partData, '紧致度', 'N/A');
          const sensitivity = SafeGetValue(partData, '敏感度', 'N/A');
          const status = SafeGetValue(partData, '状态', 'N/A');
          partInfo = `${tightness} | 敏感度:${sensitivity} | ${status}`;
          partDescription = SafeGetValue(partData, '描述', '');
        } else if (partKey === '脚部') {
          const size = SafeGetValue(partData, '大小', 'N/A');
          const sensitivity = SafeGetValue(partData, '敏感度', 'N/A');
          const status = SafeGetValue(partData, '状态', 'N/A');
          partInfo = `${size} | 敏感度:${sensitivity} | ${status}`;
          partDescription = SafeGetValue(partData, '描述', '');
        }

        bodyPartsHTML += `
          <div class="expandable-item" onclick="toggleItemDetails(this)">
            <div class="item-header">
              <span class="equipment-name">${partName}</span>
              <span class="equipment-level">${partInfo}</span>
              <span class="expand-icon">▼</span>
            </div>
