    // NPC互动相关函数
    function openNPCInteractionModal() {
      const modal = document.getElementById('npc-interaction-modal');
      if (!modal || !statDataCache) return;

      const npcListContainer = document.getElementById('npc-interaction-list');
      npcListContainer.innerHTML = '';

      // 获取NPC列表
      const npcListData = GetRawValue(statDataCache, 'NPC角色', {});
      const npcList = Object.values(npcListData).filter(item => item && typeof item === 'object' && item.基础档案);

      let hasNPCs = false;
      if (npcList.length > 0) {
        npcList.forEach(npcData => {
          const npcName = SafeGetValue(npcData, '基础档案.姓名', null);
          if (!npcName) return;
          hasNPCs = true;

          const npcItem = document.createElement('div');
          npcItem.className = 'interaction-doll-item';
          npcItem.textContent = npcName;
          npcItem.dataset.npcName = npcName;
          npcListContainer.appendChild(npcItem);
        });
      }

      if (!hasNPCs) {
        npcListContainer.innerHTML = '<p>无可用NPC。</p>';
      }

      modal.style.display = 'block';
    }

    function closeNPCInteractionModal() {
      const modal = document.getElementById('npc-interaction-modal');
      if (modal) {
        modal.style.display = 'none';
      }
    }

