          if (event.target.matches('.action-button')) {
            const selectedNPCs = Array.from(document.querySelectorAll('.interaction-doll-item.selected'))
              .map(item => item.dataset.npcName);

            if (selectedNPCs.length === 0) {
              alert('请至少选择一个NPC。');
              return;
            }

            const action = event.target.dataset.action;
            const npcNames = selectedNPCs.join('、');
            const narrative = `对${npcNames}${action}`;
            const commandToSend = `/send ${narrative}|/trigger`;

            if (typeof triggerSlash === 'function') {
              triggerSlash(commandToSend);
              closeNPCInteractionModal();
