        shopBtn.addEventListener('click', () => {
          const commandToSend = '/send 打开学园商店|/trigger';
          if (typeof triggerSlash === 'function') {
            triggerSlash(commandToSend);
          } else {
            console.error('triggerSlash function is not available.');
          }
        });
      }


      // 点击模态框外部关闭
      window.addEventListener('click', (event) => {
        if (event.target == document.getElementById('npc-interaction-modal')) {
          closeNPCInteractionModal();
        }
      });
    });

