      if (statName === 'level') {
        if (newValue < 1 || newValue > 20) return; // 等级限制1-20
      }
      if (statName === 'potential') {
        if (newValue < 5.0 || newValue > 10.0) return; // 潜力限制5.0-10.0
      }

      stats[statName] = newValue;
      availablePoints -= change;

      // 潜力值显示一位小数
      if (statName === 'potential') {
        document.getElementById(statName + '-value').textContent = stats[statName].toFixed(1);
      } else {
        document.getElementById(statName + '-value').textContent = stats[statName];
      }

      updatePointsDisplay();
      updateStatButtons();
      updateCombatPower(); // 更新性斗力显示
      updateEndurance(); // 更新忍耐力显示
    }

    function updateCombatPower() {
      const combatPower = calculateCombatPower();
      document.getElementById('combat-value').textContent = combatPower;
    }

