        if (stat === 'combat' || stat === 'endurance') return;

        const minusBtn = document.querySelector(`[onclick="changeStat('${stat}', -1)"]`);
        const plusBtn = document.querySelector(`[onclick="changeStat('${stat}', 1)"]`);
        const minus5Btn = document.querySelector(`[onclick="changeStat('${stat}', -5)"]`);
        const plus5Btn = document.querySelector(`[onclick="changeStat('${stat}', 5)"]`);
        const minus01Btn = document.querySelector(`[onclick="changeStat('${stat}', -0.1)"]`);
        const plus01Btn = document.querySelector(`[onclick="changeStat('${stat}', 0.1)"]`);
        const minus05Btn = document.querySelector(`[onclick="changeStat('${stat}', -0.5)"]`);
        const plus05Btn = document.querySelector(`[onclick="changeStat('${stat}', 0.5)"]`);

