        const isAtMax = (stat === 'charm' || stat === 'luck') ? stats[stat] >= 100 : false;
        const isLevelMax = stat === 'level' ? stats[stat] >= 20 : false;
        const isLevelMin = stat === 'level' ? stats[stat] <= 1 : false;
        const isPotentialMax = stat === 'potential' ? stats[stat] >= 10.0 : false;
        const isPotentialMin = stat === 'potential' ? stats[stat] <= 5.0 : false;

        if (minusBtn) minusBtn.disabled = stats[stat] <= 1 || isLevelMin;
        if (plusBtn) plusBtn.disabled = availablePoints <= 0 || isAtMax || isLevelMax;
        if (minus5Btn) minus5Btn.disabled = stats[stat] <= 5 || (stat === 'level' && stats[stat] <= 1);
        if (plus5Btn) plus5Btn.disabled = availablePoints < 5 || isAtMax || (stat === 'level' && stats[stat] >= 20);

        // 潜力按钮
        if (minus01Btn) minus01Btn.disabled = stats[stat] <= 5.0 || isPotentialMin;
        if (plus01Btn) plus01Btn.disabled = availablePoints <= 0 || isPotentialMax;
