      if (nextButton) nextButton.style.display = pageIndex === pages.length - 1 ? 'none' : 'inline-block';
      if (sendButton) sendButton.style.display = pageIndex === pages.length - 1 ? 'inline-block' : 'none';
      currentPage = pageIndex;
